import{_ as r,o as l,c as n,j as e,a}from"./chunks/framework.CAXxHpAX.js";const f=JSON.parse('{"title":"答疑2014-纯一直心不动道场","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/答疑2014-纯一直心不动道场.md","filePath":"60-原文段落/答疑2014-纯一直心不动道场.md","lastUpdated":1778155802000}'),o={name:"60-原文段落/答疑2014-纯一直心不动道场.md"};function _(s,t,c,d,i,p){return l(),n("div",null,[...t[0]||(t[0]=[e("h1",{id:"答疑2014-纯一直心不动道场",tabindex:"-1"},[a("答疑2014-纯一直心不动道场 "),e("a",{class:"header-anchor",href:"#答疑2014-纯一直心不动道场","aria-label":'Permalink to "答疑2014-纯一直心不动道场"'},"​")],-1),e("blockquote",null,[e("p",null,[a("来源："),e("a",{href:"/01-Raw-Sources/03_答疑专辑2014_佛道"},"03_答疑专辑2014_佛道"),a(" 切分日期：2026-05-06")])],-1),e("hr",null,null,-1),e("p",null,'了空居士：我告诉你！既然叫"无我"，开悟的人才证得无我，没有开悟的人，就有我执嘛。那么你说释迦牟尼佛吧，释迦牟尼佛你圆满成佛了，你是不是证的"无我"啊？有啊。那么三千年前，坐在我们面前的那个人又是谁呢？我说那是释迦牟尼佛，那你说，那释迦牟尼佛坐在面前就有个释迦牟尼佛吗？如果我们去说，释迦牟尼佛是哪位？释迦牟尼佛可能就会说我就是，那不是变成有我了吗？那到底释迦牟尼佛是有我还是无我。我告诉大家，无我不是我不见了，而是贪嗔痴的我没有啦，成了一个大公无私、光明磊落的我了，也就是那凡夫不见了，变成佛祖了。哈。无我不是我什么都没有，而是"身见、边见、邪见、见取见、戒取见"都没有，贪嗔痴慢疑也没有，是一个纯一直心，是一个心地清净的"我"。所以你说有我吗？要说有，原来坏习惯没有了，要说没有，我还坐在这里。这就是佛家所说的非空非有。你们凡夫，要不然就以为永远是有，要不然以为绝对是没有。哪个人言下大悟然后整个人不见了？六祖听人家诵《金刚经》言下大悟，那六袓还站在那里，说还要去黄梅拜师呢，你们一听言下开悟，那整个人就化成一团气不见了？非也非也！谢谢大家。',-1)])])}const m=r(o,[["render",_]]);export{f as __pageData,m as default};
